//! Editor help from the Havok class schema (`nemesis_xml::patch::class_schema`, generated by
//! `cargo x gen class-schema`): the class around a line, field snippets, new object skeletons,
//! pointer target checks.

use std::fmt::Write as _;

pub use nemesis_xml::patch::class_schema::{ClassSchema, FieldSchema, TypeKind};
use nemesis_xml::patch::class_schema::{class_schema_names, find_class_schema};

use crate::attribute;

/// Every class name (alphabetical).
pub fn class_names() -> Vec<&'static str> {
    let mut names: Vec<_> = class_schema_names().collect();
    names.sort_unstable();
    names
}

/// The class of an `<hkobject .. class="x" ..>` line.
pub fn class_of_line(line: &str) -> Option<&str> {
    attribute(line, "class")
}

/// The fields written in XML (not `SERIALIZE_IGNORED`), in order.
pub fn xml_fields(class: &str) -> impl Iterator<Item = &'static FieldSchema> {
    find_class_schema(class).into_iter().flat_map(|c| c.fields.iter()).filter(|f| !f.serialize_ignored)
}

/// The array element at a position of an object's text, for "which index is this?" hovers.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ArrayElement<'a> {
    /// The array field, e.g. `eventNames`.
    pub field: &'a str,
    pub index: usize,
    /// The element count it declares (`numelements`).
    pub len: Option<usize>,
}

/// Which element of which array is at 0-based `line` / `column` (chars) of an object.
///
/// Havok XML writes an array as `<hkparam name=".." numelements="N">` and its elements as one of:
/// ```text
/// <hkparam name="children" numelements="3">
///     #0105 #0106         <- whitespace separated values, any number per line
///     #0107
/// </hkparam>
/// <hkparam name="eventNames" numelements="2">
///     <hkcstring>moveStart</hkcstring>       <- one per line
///     <hkcstring>moveStop</hkcstring>
/// </hkparam>
/// <hkparam name="eventInfos" numelements="1">
///     <hkobject>                             <- a block; any line inside it counts as this element
///         <hkparam name="flags">0</hkparam>
///     </hkobject>
/// </hkparam>
/// <hkparam name="translations" numelements="1">(0.0 0.0 0.0 0.0)</hkparam>   <- on one line
/// ```
/// e.g., on `#0106` above: `children`, index 1.
pub fn array_element(object: &str, line: usize, column: usize) -> Option<ArrayElement<'_>> {
    /// An open tag around the current line. `count`: the elements seen so far (arrays only).
    enum Open<'a> {
        Object,
        Field { name: &'a str, len: Option<usize>, count: Option<usize> },
    }
    let mut stack: Vec<Open<'_>> = Vec::new();
    let token_at = |tokens: &[std::ops::Range<usize>]| tokens.iter().position(|t| t.start <= column && column <= t.end);

    for (line_no, text) in object.lines().enumerate().take(line + 1) {
        let here = line_no == line;
        let trimmed = text.trim();
        if trimmed.starts_with("<hkobject") {
            if let Some(Open::Field { count: Some(count), .. }) = stack.last_mut() {
                *count += 1;
            }
            if !trimmed.ends_with("/>") {
                stack.push(Open::Object);
            }
        } else if trimmed.starts_with("</hkobject>") || trimmed.starts_with("</hkparam>") {
            stack.pop();
        } else if let Some(rest) = trimmed.strip_prefix("<hkparam") {
            let name = attribute(rest, "name").unwrap_or_default();
            let numelements = attribute(rest, "numelements");
            let len = numelements.and_then(|n| n.parse().ok());
            if let Some(start) = text.find('>').filter(|_| trimmed.contains("</hkparam>")) {
                // Everything on one line: `<hkparam name="x" numelements="2">#01 #02</hkparam>`.
                if here && numelements.is_some() {
                    let end = text.find("</hkparam>").unwrap_or(text.len());
                    let offset = text[..=start].chars().count();
                    let tokens = array_tokens(&text[start + 1..end]);
                    let tokens: Vec<_> = tokens.into_iter().map(|t| t.start + offset..t.end + offset).collect();
                    if let Some(index) = token_at(&tokens) {
                        return Some(ArrayElement { field: name, index, len });
                    }
                }
            } else if !trimmed.ends_with("/>") {
                stack.push(Open::Field { name, len, count: numelements.map(|_| 0) });
            }
        } else if !trimmed.starts_with("<!--")
            && let Some(Open::Field { name, len, count: Some(count) }) = stack.last_mut()
        {
            let tokens = array_tokens(text);
            if here {
                let index = *count + token_at(&tokens)?;
                return Some(ArrayElement { field: name, index, len: *len });
            }
            *count += tokens.len();
        }

        if here {
            // Inside an `<hkobject>` element: the innermost array around it.
            let object_above = stack.iter().rposition(|open| matches!(open, Open::Object))?;
            return stack[..object_above].iter().rev().find_map(|open| match open {
                Open::Field { name, len, count: Some(count) } => {
                    Some(ArrayElement { field: name, index: count.saturating_sub(1), len: *len })
                }
                _ => None,
            });
        }
    }
    None
}

/// The elements in the text of an array line, as char ranges.
///
/// e.g., `  #01 #02` -> `2..5, 6..9`; `(1 2 3 4) (5 6 7 8)` -> two vectors;
/// a tag such as `<hkcstring>a b</hkcstring>` is one element.
fn array_tokens(text: &str) -> Vec<std::ops::Range<usize>> {
    let mut tokens = Vec::new();
    let is_tag = text.trim_start().starts_with('<');
    let mut start = None;
    let mut in_parens = false;
    let mut chars = 0;
    for (i, c) in text.chars().enumerate() {
        chars = i + 1;
        if c == '(' {
            in_parens = true;
        } else if c == ')' {
            in_parens = false;
        }
        if c.is_whitespace() && !in_parens && !(is_tag && start.is_some()) {
            if let Some(from) = start.take() {
                tokens.push(from..i);
            }
        } else if start.is_none() && !c.is_whitespace() {
            start = Some(i);
        }
    }
    if let Some(from) = start {
        tokens.push(from..chars);
    }
    tokens
}

/// The fields a new object has to write but does not (its own level only, not nested objects).
///
/// e.g., a `hkbEventProperty`-like class without `id` -> `["id"]`.
/// Havok's XML reader needs every field of a class, unlike Nemesis patches that only change some.
pub fn missing_fields(object: &str) -> Vec<&'static str> {
    let Some(class) = object.lines().next().and_then(|line| attribute(line, "class")) else { return Vec::new() };
    // `depth` = open tags below the top `<hkobject>`: only 0 is the object's own level.
    let mut depth = 0_usize;
    let mut written: Vec<&str> = Vec::new();
    for line in object.lines().skip(1) {
        let trimmed = line.trim();
        if trimmed.starts_with("</hkobject>") || trimmed.starts_with("</hkparam>") {
            depth = depth.saturating_sub(1);
        } else if trimmed.starts_with("<hkobject") {
            depth += usize::from(!trimmed.ends_with("/>"));
        } else if let Some(rest) = trimmed.strip_prefix("<hkparam") {
            if depth == 0 {
                written.extend(attribute(rest, "name"));
            }
            depth += usize::from(!trimmed.contains("</hkparam>") && !trimmed.ends_with("/>"));
        }
    }
    xml_fields(class).map(|field| field.name).filter(|name| !written.contains(name)).collect()
}

/// `<signature of the class>`, e.g. `hkbModifierList` -> `0xa4180ca1`.
pub fn class_signature(class: &str) -> Option<&'static str> {
    find_class_schema(class).map(|schema| schema.signature)
}

/// The parents of `class`, nearest first. e.g., `hkbModifierList` -> `hkbModifier`, ...
pub fn class_parents(class: &str) -> Vec<&'static str> {
    let mut parents = Vec::new();
    let mut current = find_class_schema(class).and_then(|schema| schema.parent);
    while let Some(name) = current {
        parents.push(name);
        current = find_class_schema(name).and_then(|schema| schema.parent);
    }
    parents
}

/// `line` (an `<hkobject .. class="x" ..>` tag) with the signature its class has. `None`: it has it
/// already, or the line has no known class.
///
/// e.g., `<hkobject name="#a" class="hkbModifierList" signature="0x0">`
/// -> `<hkobject name="#a" class="hkbModifierList" signature="0xa4180ca1">`
pub fn line_with_signature(line: &str) -> Option<String> {
    let trimmed = line.trim_start();
    let rest = trimmed.strip_prefix("<hkobject")?;
    let signature = class_signature(attribute(rest, "class")?)?;
    match attribute(rest, "signature") {
        Some(current) if same_signature(current, signature) => None,
        Some(current) => {
            Some(line.replacen(&format!("signature=\"{current}\""), &format!("signature=\"{signature}\""), 1))
        }
        None => {
            let at = line.rfind('>')?;
            let before = line[..at].trim_end_matches('/').trim_end();
            Some(format!("{before} signature=\"{signature}\"{}", &line[before.len()..]))
        }
    }
}

/// Numbers, not text: `0x95aca5d` is `0x095ACA5D`.
fn same_signature(a: &str, b: &str) -> bool {
    let value = |s: &str| u32::from_str_radix(s.trim_start_matches("0x"), 16).ok();
    value(a).is_some() && value(a) == value(b)
}

/// Is `class` `base` or one of its subclasses?
pub fn is_subclass(class: &str, base: &str) -> bool {
    let mut current = Some(class);
    while let Some(name) = current {
        if name == base {
            return true;
        }
        current = find_class_schema(name).and_then(|c| c.parent);
    }
    false
}

/// The class (and its XML fields) of the innermost `<hkobject>` open at 0-based `line` of an
/// object text. A classless nested `<hkobject>` gets the class from its field's type.
pub fn field_context(object: &str, line: usize) -> Option<(String, Vec<&'static FieldSchema>)> {
    let mut objects: Vec<Option<&str>> = Vec::new();
    let mut fields: Vec<Option<&'static str>> = Vec::new();
    for text in object.lines().take(line) {
        walk_line(text, &mut objects, &mut fields);
    }
    let class = objects.last().copied().flatten()?;
    find_class_schema(class)?;
    Some((class.to_string(), xml_fields(class).collect()))
}

/// Tracks the open objects (their classes) and fields (the class their nested objects have).
fn walk_line<'a>(text: &'a str, objects: &mut Vec<Option<&'a str>>, fields: &mut Vec<Option<&'static str>>) {
    let trimmed = text.trim();
    if let Some(rest) = trimmed.strip_prefix("<hkobject") {
        let class = attribute(rest, "class").or_else(|| fields.last().copied().flatten());
        objects.push(class);
        if trimmed.ends_with("/>") {
            objects.pop();
        }
    } else if trimmed.starts_with("</hkobject>") {
        objects.pop();
    } else if let Some(rest) = trimmed.strip_prefix("<hkparam") {
        if !trimmed.contains("</hkparam>") && !trimmed.ends_with("/>") {
            let field = field_of(objects.last().copied().flatten(), attribute(rest, "name").unwrap_or_default());
            // Only structs (inline objects) give their class to a nested `<hkobject>`.
            fields.push(
                field.filter(|f| f.kind == TypeKind::Struct || f.sub_kind == TypeKind::Struct).and_then(|f| f.class),
            );
        }
    } else if trimmed.starts_with("</hkparam>") {
        fields.pop();
    }
}

fn field_of(class: Option<&str>, name: &str) -> Option<&'static FieldSchema> {
    find_class_schema(class?)?.fields.iter().find(|f| f.name == name)
}

/// `<hkparam name="..">default</hkparam>` for `field`; nested lines are indented for a field at
/// `depth` tabs. No leading indent, no trailing newline.
pub fn field_snippet(field: &FieldSchema, depth: usize) -> String {
    let mut out = String::new();
    field_skeleton(&mut out, depth, field, 0);
    out.trim_start_matches('\t').trim_end().to_string()
}

/// A new object `id` of `class`: every XML field at its default (`null`, `0`, `false`, the first
/// enum value, empty arrays, nested structs filled the same way), with the class signature.
pub fn skeleton(class: &str, id: &str) -> Option<String> {
    let schema = find_class_schema(class)?;
    let mut out = format!("\t\t<hkobject name=\"{id}\" class=\"{class}\" signature=\"{}\">\n", schema.signature);
    for field in xml_fields(class) {
        field_skeleton(&mut out, 3, field, 0);
    }
    out.push_str("\t\t</hkobject>\n");
    Some(out)
}

fn field_skeleton(out: &mut String, depth: usize, field: &FieldSchema, nesting: usize) {
    let (indent, name) = ("\t".repeat(depth), field.name);
    let value = match field.kind {
        TypeKind::Array | TypeKind::SimpleArray => {
            let _ = writeln!(out, "{indent}<hkparam name=\"{name}\" numelements=\"0\"></hkparam>");
            return;
        }
        // An inline struct (e.g. `hkbEventProperty`): its fields, a few levels deep at most.
        TypeKind::Struct if nesting < 4 => {
            let _ = writeln!(out, "{indent}<hkparam name=\"{name}\">");
            let _ = writeln!(out, "{indent}\t<hkobject>");
            for nested in field.class.into_iter().flat_map(xml_fields) {
                field_skeleton(out, depth + 2, nested, nesting + 1);
            }
            let _ = writeln!(out, "{indent}\t</hkobject>");
            let _ = writeln!(out, "{indent}</hkparam>");
            return;
        }
        kind => default_value(field, kind),
    };
    let _ = writeln!(out, "{indent}<hkparam name=\"{name}\">{value}</hkparam>");
}

/// XML default of a scalar field.
fn default_value(field: &FieldSchema, kind: TypeKind) -> &'static str {
    const ZERO4: &str = "(0.000000 0.000000 0.000000 0.000000)";
    match kind {
        TypeKind::Pointer => "null",
        TypeKind::Bool => "false",
        TypeKind::Real | TypeKind::Half => "0.000000",
        TypeKind::Enum => field.values.first().copied().unwrap_or("0"),
        TypeKind::Vector4 | TypeKind::Quaternion => ZERO4,
        TypeKind::Matrix3 | TypeKind::Rotation | TypeKind::QsTransform => {
            "(0.000000 0.000000 0.000000 0.000000)(0.000000 0.000000 0.000000 0.000000)(0.000000 0.000000 0.000000 0.000000)"
        }
        TypeKind::Matrix4 | TypeKind::Transform => {
            "(0.000000 0.000000 0.000000 0.000000)(0.000000 0.000000 0.000000 0.000000)(0.000000 0.000000 0.000000 0.000000)(0.000000 0.000000 0.000000 0.000000)"
        }
        TypeKind::CString | TypeKind::StringPtr | TypeKind::Variant => "",
        // integers, flags (`0` = none), char
        _ => "0",
    }
}

/// A pointer to an object of the wrong class.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PointerProblem {
    /// 0-based line in the checked text.
    pub line: usize,
    pub message: String,
}

/// Checks every `#pointer` of an object: the target exists and has the field's class.
///
/// `class_of` returns a target's class; it must be the field's pointer class or a subclass, e.g.
/// `variableBindingSet` -> `hkbVariableBindingSet`. Nemesis variables (`$...$`) are not checked.
pub fn check_pointers<'c>(object: &str, class_of: &dyn Fn(&str) -> Option<&'c str>) -> Vec<PointerProblem> {
    let mut problems = Vec::new();
    let mut objects: Vec<Option<&str>> = Vec::new();
    let mut fields: Vec<Option<&'static str>> = Vec::new();
    // The pointer class of the open array field (pointers on their own lines).
    let mut open_pointer_field: Vec<Option<&'static FieldSchema>> = Vec::new();

    for (line_no, text) in object.lines().enumerate() {
        let trimmed = text.trim();
        let mut check = |pointer: &str, field: &FieldSchema| {
            if pointer == "null" || !pointer.starts_with('#') {
                return;
            }
            let Some(expected) = field.class else { return };
            match class_of(pointer) {
                None => {
                    problems.push(PointerProblem { line: line_no, message: format!("`{pointer}` does not exist.") });
                }
                Some(actual) if !is_subclass(actual, expected) => problems.push(PointerProblem {
                    line: line_no,
                    message: format!("`{}` expects `{expected}`, but `{pointer}` is `{actual}`.", field.name),
                }),
                Some(_) => {}
            }
        };

        if let Some(rest) = trimmed.strip_prefix("<hkparam")
            && let Some(field) =
                field_of(objects.last().copied().flatten(), attribute(rest, "name").unwrap_or_default())
        {
            let is_pointer = field.kind == TypeKind::Pointer || field.sub_kind == TypeKind::Pointer;
            // `<hkparam name="x">#0001</hkparam>` or `<hkparam name="xs" ...>#0001 #0002</hkparam>`
            if is_pointer && let Some((_, value)) = rest.split_once('>') {
                let value = value.split("</hkparam>").next().unwrap_or_default();
                value.split_whitespace().for_each(|p| check(p, field));
            }
            if !trimmed.contains("</hkparam>") {
                open_pointer_field.push(is_pointer.then_some(field));
            }
        } else if trimmed.starts_with("</hkparam>") {
            open_pointer_field.pop();
        } else if trimmed.starts_with('#')
            && let Some(Some(field)) = open_pointer_field.last()
        {
            trimmed.split_whitespace().for_each(|p| check(p, field));
        }
        walk_line(text, &mut objects, &mut fields);
    }
    problems
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_array_elements() {
        let object = "<hkobject name=\"#1\" class=\"x\">\n<hkparam name=\"a\" numelements=\"3\">\n\t#01 #02\n\t#03\n</hkparam>\n<hkparam name=\"b\" numelements=\"2\">\n<hkobject>\n<hkparam name=\"flags\">0</hkparam>\n</hkobject>\n<hkobject>\n<hkparam name=\"flags\">1</hkparam>\n</hkobject>\n</hkparam>\n<hkparam name=\"c\" numelements=\"2\">(1 2) (3 4)</hkparam>\n<hkparam name=\"d\">1</hkparam>\n</hkobject>\n";
        let element = |line, column| array_element(object, line, column).map(|e| (e.field, e.index));
        assert_eq!(element(2, 1), Some(("a", 0)));
        assert_eq!(element(2, 5), Some(("a", 1)));
        assert_eq!(element(3, 2), Some(("a", 2)));
        assert_eq!(element(7, 3), Some(("b", 0)));
        assert_eq!(element(10, 3), Some(("b", 1)));
        // `<hkparam name="c" numelements="2">` is 34 chars.
        assert_eq!(element(13, 36), Some(("c", 0)));
        assert_eq!(element(13, 40), Some(("c", 1)));
        assert_eq!(element(14, 2), None);
    }

    #[test]
    fn skeleton_has_no_missing_fields_and_passes_the_parser() {
        let text = skeleton("hkbClipGenerator", "#mymod$0").unwrap();
        assert_eq!(missing_fields(&text), Vec::<&str>::new());
        crate::validate(&text).unwrap();

        let without = text.lines().filter(|l| !l.contains("\"mode\"")).collect::<Vec<_>>().join("\n");
        assert_eq!(missing_fields(&without), ["mode"]);
    }

    const OBJECT: &str = "\t\t<hkobject name=\"#0106\" class=\"hkbModifierList\" signature=\"0xa4180ca1\">
\t\t\t<hkparam name=\"variableBindingSet\">#0001</hkparam>
\t\t\t<hkparam name=\"modifiers\" numelements=\"2\">
\t\t\t\t#0105 #0002
\t\t\t</hkparam>
\t\t</hkobject>
";

    #[test]
    fn context_and_skeleton() {
        let (class, fields) = field_context(OBJECT, 1).unwrap();
        assert_eq!(class, "hkbModifierList");
        assert!(fields.iter().all(|f| !f.serialize_ignored));
        let enable = fields.iter().find(|f| f.name == "enable").unwrap();
        assert_eq!(field_snippet(enable, 3), "<hkparam name=\"enable\">false</hkparam>");

        let new = skeleton("hkbModifierList", "#mymod$0").unwrap();
        assert!(new.contains("signature=\"0xa4180ca1\""));
        assert!(!new.contains("referenceCount"));
        crate::validate(&new).unwrap();
        assert!(crate::check_fields(&new).is_empty(), "{new}");
    }

    #[test]
    fn pointer_classes() {
        assert!(is_subclass("hkbClipGenerator", "hkbGenerator"));
        let class_of = |id: &str| match id {
            "#0001" => Some("hkbClipGenerator"), // not a binding set
            "#0105" => Some("hkbEvaluateExpressionModifier"),
            _ => None,
        };
        let problems = check_pointers(OBJECT, &class_of);
        let lines: Vec<_> = problems.iter().map(|p| p.line).collect();
        assert_eq!(lines, [1, 3], "{problems:?}"); // wrong class, `#0002` missing
    }
}
